using System;
using System.Reflection;
using System.Linq;

var asm = Assembly.LoadFrom("/home/runner/.nuget/packages/xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll");
var types = asm.GetTypes().Where(t => t.Name == "FactAttribute" || t.Name == "TheoryAttribute");
foreach (var t in types) {
    Console.WriteLine($"{t.FullName}:");
    foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)) {
        var pars = string.Join(", ", Array.ConvertAll(c.GetParameters(), p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  Ctor({pars})");
    }
}
EOF
